import 'package:cloud_firestore/cloud_firestore.dart';
import '../models/appointment_model.dart';
class AppointmentRepository { AppointmentRepository(this._db); final FirebaseFirestore _db; Future<void> book(AppointmentModel appointment) async { final ref=_db.collection('appointments').doc(appointment.id); await _db.runTransaction((transaction) async { final clashes=await _db.collection('appointments').where('advisorId',isEqualTo:appointment.advisorId).where('startsAt',isEqualTo:Timestamp.fromDate(appointment.startsAt)).where('status',isEqualTo:AppointmentStatus.booked.name).limit(1).get(); if(clashes.docs.isNotEmpty) throw StateError('هذا الموعد لم يعد متاحاً.'); transaction.set(ref,appointment.toMap()); }); } Future<void> cancel(String id)=>_db.collection('appointments').doc(id).update({'status':AppointmentStatus.cancelled.name,'updatedAt':FieldValue.serverTimestamp()}); }
